# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of linalg.tensorinv for Ascend 910B.

tensorinv(A, ind): fold the first `ind` dims into rows (n) and the rest into
columns (m); the call is legal only when m == n.  The result is inv(M) reshaped
to A.shape[ind:] + A.shape[:ind].

Both device kernels use grid=(1,) because tensorinv fuses every tensor
dimension into exactly one n x n matrix (no batch axis to parallelise).

  * fused kernel  - pivoted Gauss-Jordan carrying the augmented [A | I] tile in
    on-chip memory (small n),
  * blocked kernel - the same algorithm streaming BLOCK-wide strips from global
    memory (n larger than the on-chip tile).

The inverse is produced entirely by the Triton kernels; the host wrapper only
validates shapes, allocates the output and launches.
"""

import torch
import triton
import triton.language as tl

# Largest n for which the augmented [BLOCK_N, 2*BLOCK_N] fp32 tile is kept
# fully resident on chip (n=32 -> 8 KB tile; BLOCK_N=64 needs ~230 KB of UB and
# overflows the 192 KB budget).
_FUSED_MAX_N = 32
# Strip width for the streaming variant.
_BLOCK = 32


@triton.jit(do_not_specialize=["n"])
def _tensorinv_fused_kernel(A, Out, n, BLOCK_N: tl.constexpr):
    r = tl.arange(0, BLOCK_N)
    c = tl.arange(0, 2 * BLOCK_N)
    r2 = r[:, None]
    c2 = c[None, :]

    # Augmented tile [A | I]; everything outside the valid n x n block is zero.
    a = tl.load(A + r2 * n + c2, mask=(r2 < n) & (c2 < n), other=0.0).to(tl.float32)
    a = tl.where((r2 < n) & (c2 >= n) & (c2 < 2 * n) & ((c2 - n) == r2), 1.0, a)

    # Left block ends as the permutation matrix Pi (Pi[p_k, k] = 1) because the
    # pivot row is never moved.  The inverse row k is E[p_k], so the store must
    # place tile row k at output row p_k, i.e. it needs the inverse
    # permutation: addr[p_k] = k.
    used = tl.zeros((BLOCK_N,), dtype=tl.int32)
    addr = tl.arange(0, BLOCK_N)

    for k in range(0, n):
        # --- pivot: largest |A[i, k]| among the rows not used yet ---
        col = tl.sum(tl.where(c2 == k, a, 0.0), axis=1)
        av = tl.where((used == 0) & (r < n), tl.abs(col), -1.0)
        prow = tl.argmax(av, axis=0)

        # --- one rank-1 update both normalises the pivot row and eliminates
        #     column k from every other row ---
        pq = tl.sum(tl.where(r == prow, col, 0.0), axis=0)
        inv = 1.0 / pq
        fac = tl.where(r == prow, 1.0 - inv, col * inv)
        if BLOCK_N <= 2:
            # Tiny tiles (n <= 2): broadcasting the pivot row with a gather
            # copy is cheaper than an axis-0 reduction plus its barrier.  For
            # larger tiles the gather scalarises and the reduction wins.
            idx = tl.zeros((BLOCK_N, 2 * BLOCK_N), dtype=tl.int32) + prow
            a = a - fac[:, None] * tl.gather(a, idx, axis=0)
        else:
            row_p = tl.sum(tl.where(r2 == prow, a, 0.0), axis=0)
            a = a - fac[:, None] * row_p[None, :]

        used = tl.where(r == prow, 1, used)
        addr = tl.where(r == prow, k, addr)

    tl.store(
        Out + addr[:, None] * n + (c2 - n),
        a.to(Out.dtype.element_ty),
        mask=(r2 < n) & (c2 >= n) & (c2 < 2 * n),
    )


@triton.jit(do_not_specialize=["n"])
def _tensorinv_blocked_kernel(A, Out, Work, n, BLOCK: tl.constexpr):
    r0 = tl.arange(0, BLOCK)

    # Work <- A (fp32), Out <- I
    for i0 in range(0, n, BLOCK):
        rows = i0 + r0
        rm = rows < n
        for j0 in range(0, n, BLOCK):
            cols = j0 + r0
            cm = cols < n
            m2 = rm[:, None] & cm[None, :]
            tap = tl.load(A + rows[:, None] * n + cols[None, :], mask=m2, other=0.0).to(
                tl.float32
            )
            tl.store(Work + rows[:, None] * n + cols[None, :], tap, mask=m2)
            ident = tl.where(rows[:, None] == cols[None, :], 1.0, 0.0)
            tl.store(
                Out + rows[:, None] * n + cols[None, :],
                ident.to(Out.dtype.element_ty),
                mask=m2,
            )
    tl.debug_barrier()

    for k in range(0, n):
        # --- pivot search down column k (1D strips) ---
        best_val = tl.full((), -1.0, dtype=tl.float32)
        best_row = tl.full((), 0, dtype=tl.int32)
        for i0 in range(k, n, BLOCK):
            rows = i0 + r0
            colv = tl.load(Work + rows * n + k, mask=rows < n, other=0.0).to(tl.float32)
            av = tl.where((rows >= k) & (rows < n), tl.abs(colv), -1.0)
            tmax = tl.max(av, axis=0)
            trow = tl.min(tl.where(av == tmax, rows, n), axis=0)
            better = tmax > best_val
            best_row = tl.where(better, trow, best_row)
            best_val = tl.where(better, tmax, best_val)

        # --- swap rows k and best_row in Work and Out ---
        for j0 in range(0, n, BLOCK):
            cols = j0 + r0
            cm = cols < n
            wa = tl.load(Work + k * n + cols, mask=cm, other=0.0).to(tl.float32)
            wb = tl.load(Work + best_row * n + cols, mask=cm, other=0.0).to(tl.float32)
            tl.store(Work + k * n + cols, wb, mask=cm)
            tl.store(Work + best_row * n + cols, wa, mask=cm)
            oa = tl.load(Out + k * n + cols, mask=cm, other=0.0).to(tl.float32)
            ob = tl.load(Out + best_row * n + cols, mask=cm, other=0.0).to(tl.float32)
            tl.store(Out + k * n + cols, ob.to(Out.dtype.element_ty), mask=cm)
            tl.store(Out + best_row * n + cols, oa.to(Out.dtype.element_ty), mask=cm)
        tl.debug_barrier()

        # --- normalise row k ---
        pq = tl.load(Work + k * n + k).to(tl.float32)
        inv = 1.0 / pq
        for j0 in range(0, n, BLOCK):
            cols = j0 + r0
            cm = cols < n
            wr = tl.load(Work + k * n + cols, mask=cm, other=0.0).to(tl.float32)
            orow = tl.load(Out + k * n + cols, mask=cm, other=0.0).to(tl.float32)
            tl.store(Work + k * n + cols, wr * inv, mask=cm)
            tl.store(Out + k * n + cols, (orow * inv).to(Out.dtype.element_ty), mask=cm)
        tl.debug_barrier()

        # --- eliminate column k from every other row ---
        for i0 in range(0, n, BLOCK):
            rows = i0 + r0
            rm = rows < n
            fac = tl.load(Work + rows * n + k, mask=rm, other=0.0).to(tl.float32)
            fac = tl.where(rows != k, fac, 0.0)
            for j0 in range(0, n, BLOCK):
                cols = j0 + r0
                m2 = rm[:, None] & (cols < n)[None, :]
                urow = tl.load(Work + k * n + cols, mask=cols < n, other=0.0).to(
                    tl.float32
                )
                urow2 = tl.load(Out + k * n + cols, mask=cols < n, other=0.0).to(
                    tl.float32
                )
                wt = tl.load(
                    Work + rows[:, None] * n + cols[None, :], mask=m2, other=0.0
                ).to(tl.float32)
                ot = tl.load(
                    Out + rows[:, None] * n + cols[None, :], mask=m2, other=0.0
                ).to(tl.float32)
                tl.store(
                    Work + rows[:, None] * n + cols[None, :],
                    wt - fac[:, None] * urow[None, :],
                    mask=m2,
                )
                tl.store(
                    Out + rows[:, None] * n + cols[None, :],
                    (ot - fac[:, None] * urow2[None, :]).to(Out.dtype.element_ty),
                    mask=m2,
                )
        tl.debug_barrier()


def _check_input(A, ind):
    if ind <= 0:
        raise RuntimeError(
            "linalg.tensorinv: Expected a strictly positive integer for "
            f"'ind', but got {ind}"
        )
    if A.dim() < 2:
        raise RuntimeError(
            f"linalg.tensorinv: Expected input to be at least 2D, got {A.dim()}D"
        )
    if ind > A.dim():
        raise RuntimeError(
            "linalg.tensorinv: Expected 0 <= ind <= input.dim(), "
            f"got ind={ind} for input.dim()={A.dim()}"
        )
    m = 1
    for i in range(ind):
        m *= A.shape[i]
    n = 1
    for i in range(ind, A.dim()):
        n *= A.shape[i]
    if m != n:
        raise RuntimeError(
            "linalg.tensorinv: Expected self to satisfy the requirement "
            "prod(self.shape[ind:]) == prod(self.shape[:ind]), "
            f"but got {n} != {m}"
        )
    return n


def linalg_tensorinv(A, ind=2, *, out=None):
    """Multiplicative inverse of tensordot (torch.linalg.tensorinv)."""
    ind = int(ind)
    n = _check_input(A, ind)

    out_shape = tuple(A.shape[ind:]) + tuple(A.shape[:ind])
    if out is not None and out.shape == out_shape and out.is_contiguous():
        target = out
    else:
        target = torch.empty(out_shape, dtype=A.dtype, device=A.device)

    if n != 0:
        src = A if A.is_contiguous() else A.contiguous()
        if n <= _FUSED_MAX_N:
            bn = triton.next_power_of_2(n)
            # n <= 2 keeps a [2,4] tile, which the kernel drives with the
            # gather broadcast; larger n is padded to at least 8 rows so the
            # vector unit is not under-filled.
            _tensorinv_fused_kernel[(1,)](
                src, target, n, BLOCK_N=(max(2, bn) if bn <= 2 else max(8, bn))
            )
        else:
            work = torch.empty((n, n), dtype=torch.float32, device=A.device)
            _tensorinv_blocked_kernel[(1,)](src, target, work, n, BLOCK=_BLOCK)

    if out is not None and target is not out:
        out.copy_(target)
        return out
    return target
